const D = [['personality','personality.co'],['lovestyle','lovestyle.co'],['mindspree','mindspree.io'],
  ['myimage','myimage.io'],['resumewise','resumewise.com'],['pdfhelp','pdfhelp.com'],['unicopy','unicopy.ai'],
  ['realchecker','realchecker.com'],['aichat','chatbotonline.ai'],['myqrcode','myqrcode.com'],
  ['brainiq','brainiqtest.com'],['qrcreate','qrcreate.com'],['vinready','vinready.com']];
const base = 'https://www.trustpilot.com/review/';
const out = D.map(([b, d]) => ({ json: { brand: b, check: 'p1', url: base + d } }));
out.push({ json: { brand: 'personality', check: 'p1_languages_all', url: base + 'personality.co?languages=all' } });
for (const p of [2, 50, 130]) out.push({ json: { brand: 'personality', check: 'p' + p, url: base + 'personality.co?page=' + p } });
return out;

const reqs = $('Build URLs').all().map(i => i.json);
const out = [];
$input.all().forEach((it, i) => {
  const r = reqs[i] || {};
  const j = it.json || {};
  const body = typeof j.body === 'string' ? j.body : (typeof j.data === 'string' ? j.data : '');
  const res = { status: j.statusCode || (j.error ? 'error' : '?'), bytes: body.length };
  if (j.error) res.error = String((j.error && j.error.message) || JSON.stringify(j.error)).slice(0, 200);
  const m = body.match(/<script id="__NEXT_DATA__" type="application\/json"[^>]*>([\s\S]*?)<\/script>/);
  res.has_next_data = !!m;
  res.challenge_hint = !m && /end-of-the-line|are you human|captcha|access denied|cf-chl|just a moment/i.test(body);
  if (!m && body) res.body_head = body.replace(/\s+/g, ' ').slice(0, 300);
  if (m) {
    try {
      const nd = JSON.parse(m[1]);
      const pp = (nd.props && nd.props.pageProps) || {};
      res.pageProps_keys = Object.keys(pp).slice(0, 40);
      const bu = pp.businessUnit || {};
      res.business = { name: bu.displayName, reviews: bu.numberOfReviews, trustScore: bu.trustScore, stars: bu.stars };
      const rv = Array.isArray(pp.reviews) ? pp.reviews : [];
      res.reviews_on_page = rv.length;
      if (rv.length) {
        res.review_keys = Object.keys(rv[0]).slice(0, 30);
        res.dates_keys = rv[0].dates ? Object.keys(rv[0].dates) : null;
        const pub = rv.map(x => x.dates && x.dates.publishedDate).filter(Boolean).sort();
        res.newest_published = pub[pub.length - 1];
        res.oldest_published = pub[0];
        res.ratings = rv.map(x => x.rating);
        res.languages = Array.from(new Set(rv.map(x => x.language)));
        res.sample_id = rv[0].id;
      }
      const fl = pp.filters || {};
      res.pagination = fl.pagination || null;
      res.filters_keys = Object.keys(fl).slice(0, 20);
    } catch (e) { res.parse_error = String(e.message).slice(0, 200); }
  }
  out.push({ json: { brand: r.brand, check_name: r.check, result: JSON.stringify(res).slice(0, 6000) } });
});
return out;
